#!/usr/bin/env python3

import base64
import subprocess
import sys
import os
import gi
gi.require_version('Gtk', '3.0')
from gi.repository import Gtk, Gdk, GdkPixbuf, Gio, GLib

LOGO_DARK = ""

LOGO_LIGHT = ""

def is_dark_mode():
    try:
        settings = Gtk.Settings.get_default()
        style = settings.get_property("gtk-theme-name").lower()
        if "dark" in style:
            return True
    except:
        pass
    try:
        result = subprocess.run(
            ["gsettings", "get", "org.gnome.desktop.interface", "color-scheme"],
            capture_output=True, text=True, timeout=2
        )
        if "dark" in result.stdout.lower():
            return True
    except:
        pass
    return False

def get_logo_pixbuf():
    dark = is_dark_mode()
    b64 = LOGO_DARK if dark else LOGO_LIGHT
    raw = base64.b64decode(b64)
    stream = Gio.MemoryInputStream.new_from_bytes(GLib.Bytes(raw))
    pixbuf = GdkPixbuf.Pixbuf.new_from_stream(stream)
    return pixbuf.scale_simple(280, 70, GdkPixbuf.InterpType.BILINEAR)

class ShutdownDialog(Gtk.Window):
    def __init__(self):
        super().__init__(title="Shut Down EDYOU OS")
        self.set_decorated(False)
        self.set_resizable(False)
        self.set_keep_above(True)
        self.set_type_hint(Gdk.WindowTypeHint.DIALOG)
        self.set_gravity(Gdk.Gravity.CENTER)
        self.set_position(Gtk.WindowPosition.CENTER)
        self.set_default_size(480, 250)
        self.set_size_request(480, 250)

        # Set window icon from Fluent Icon Theme
        self.set_icon_name("system-shutdown-symbolic")

        screen = Gdk.Screen.get_default()
        visual = screen.get_rgba_visual()
        if visual:
            self.set_visual(visual)

        dark = is_dark_mode()
        bg = "#1e1e1e" if dark else "#f2f2f2"
        fg = "#ffffff" if dark else "#000000"
        btn = "#2d2d2d" if dark else "#e8e8e8"
        btn_h = "#3d3d3d" if dark else "#dcdcdc"
        sep = "#3d3d3d" if dark else "#cccccc"

        css = f"""
            window {{
                background-color: transparent;
                border-radius: 16px;
            }}
            #rounded-bg {{
                background-color: {bg};
                border-radius: 16px;
            }}
            button {{
                background: {btn};
                color: {fg};
                border: none;
                border-radius: 6px;
                padding: 8px 16px;
            }}
            button:hover {{
                background: {btn_h};
            }}
            button:focus {{
                outline: none;
            }}
            combobox {{
                background: {btn};
                color: {fg};
                border: 1px solid {sep};
                border-radius: 4px;
                padding: 4px;
            }}
            label {{
                color: {fg};
            }}
            separator {{
                background: {sep};
                min-height: 1px;
            }}
        """.encode()

        p = Gtk.CssProvider()
        p.load_from_data(css)
        self.get_style_context().add_provider(p, 600)

        self.connect("key-press-event", self.on_key_press)

        outer = Gtk.Box()
        outer.set_name("rounded-bg")
        outer.get_style_context().add_provider(p, 600)
        self.add(outer)

        inner = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=8)
        inner.set_margin_top(16)
        inner.set_margin_bottom(16)
        inner.set_margin_start(16)
        inner.set_margin_end(16)
        outer.pack_start(inner, True, True, 0)

        try:
            pixbuf = get_logo_pixbuf()
            img = Gtk.Image.new_from_pixbuf(pixbuf)
        except:
            img = Gtk.Label(label="EDYOU OS")
            img.get_style_context().add_provider(p, 600)
        img.set_halign(Gtk.Align.CENTER)
        img.set_valign(Gtk.Align.CENTER)
        inner.pack_start(img, False, False, 0)

        sep = Gtk.HSeparator()
        inner.pack_start(sep, False, False, 0)

        lbl = Gtk.Label(label="What do you want the computer to do?")
        lbl.set_halign(Gtk.Align.CENTER)
        lbl.set_valign(Gtk.Align.CENTER)
        inner.pack_start(lbl, False, False, 0)

        self.combo = Gtk.ComboBoxText()
        for opt in ["Shut Down", "Restart", "Suspend", "Log Out"]:
            self.combo.append_text(opt)
        self.combo.set_active(0)
        self.combo.set_size_request(200, 32)
        self.combo.set_halign(Gtk.Align.CENTER)
        inner.pack_start(self.combo, False, False, 4)

        spacer = Gtk.Box()
        spacer.set_size_request(-1, 16)
        inner.pack_start(spacer, False, False, 0)

        btns = Gtk.Box(spacing=12)
        btns.set_halign(Gtk.Align.CENTER)
        inner.pack_start(btns, False, False, 0)

        for lbl_text, handler in [("OK", self.on_ok), ("Cancel", self.on_cancel), ("Help", self.on_help)]:
            b = Gtk.Button(label=lbl_text)
            b.connect("clicked", handler)
            btns.pack_start(b, False, False, 0)

        self.ok_btn = btns.get_children()[0]
        self.connect("show", lambda w: self.ok_btn.grab_focus())

    def focus_is_within_combo(self, widget):
        while widget is not None:
            if widget is self.combo:
                return True
            widget = widget.get_parent()
        return False

    def on_key_press(self, w, e):
        if e.keyval == 65307:
            self.on_cancel(None)
            return True

        if e.keyval in (65293, 65421):
            focus = self.get_focus()
            if focus is None or focus is self.ok_btn or self.focus_is_within_combo(focus):
                self.on_ok(None)
                return True
            return False

        return False

    def on_ok(self, w):
        act = self.combo.get_active_text()
        self.destroy()
        Gtk.main_quit()
        is_root = os.geteuid() == 0
        if act == "Shut Down":
            cmd = ["systemctl", "poweroff"] if is_root else ["sudo", "/usr/bin/systemctl", "poweroff"]
        elif act == "Restart":
            cmd = ["systemctl", "reboot"] if is_root else ["sudo", "/usr/bin/systemctl", "reboot"]
        elif act == "Suspend":
            cmd = ["systemctl", "suspend"] if is_root else ["sudo", "/usr/bin/systemctl", "suspend"]
        elif act == "Log Out":
            if is_root:
                user = os.environ.get("SUDO_USER", os.environ.get("USER", "nobody"))
                cmd = ["sudo", "-u", user, "gnome-session-quit", "--logout", "--no-prompt"]
            else:
                cmd = ["gnome-session-quit", "--logout", "--no-prompt"]
        else:
            return
        try:
            subprocess.Popen(
                cmd,
                stdout=subprocess.DEVNULL,
                stderr=open("/tmp/shutdown_dialog.err", "a")
            )
        except Exception as e:
            with open("/tmp/shutdown_dialog.err", "a") as f:
                f.write(f"on_ok failed for {act}: {e}\n")

    def on_cancel(self, w):
        self.destroy()
        Gtk.main_quit()

    def on_help(self, w):
        try:
            subprocess.Popen(["xdg-open", "https://edyou-os.vercel.app/docs.html#faq"])
        except:
            pass

def main():
    # Allow running under X11 or Wayland sessions. Some Wayland sessions
    # do not set DISPLAY but do set WAYLAND_DISPLAY — accept either.
    if not (os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY")):
        sys.exit(1)
    Gtk.init()
    d = ShutdownDialog()
    d.show_all()
    d.connect("destroy", Gtk.main_quit)
    Gtk.main()

if __name__ == "__main__":
    main()
